const status=s=>`<span class="status ${s==='Gecikmiş'?'overdue':s==='Ödendi'?'paid':s==='Bugün'?'today':'pending'}">${s}</span>`;
function person(t){return `<span class="person"><span class="avatar ${t.color}">${t.initials}</span><span><b>${t.name}</b><small>${t.property}</small></span></span>`}
function render(){
  $('tenantCount').textContent=tenants.length;$('activeTenantNum').innerHTML=`${tenants.length} <span>kişi</span>`;
  $('dueTenantList').innerHTML=tenants.filter(t=>!['Ödendi','Silindi','Feshedildi'].includes(t.payment)).slice(0,3).map(t=>`<div class="due-row"><span class="avatar ${t.color}">${t.initials}</span><span><b>${t.name}</b><small>${t.property}</small></span><span class="due-rent"><b>${cash(t.rent)}</b></span>${status(displayPaymentStatus(t))}</div>`).join('');
  $('tenantTableRows').innerHTML=tenants.map(t=>`<div class="trow">${person(t)}<span class="property-text">${t.property}</span><span class="amount">${cash(t.rent)}</span><span>Her ayın ${t.day}'u</span>${status(t.payment)}<span class="more-row">•••</span></div>`).join('');
  $('paymentTableRows').innerHTML=tenants.map((t,i)=>t.paymentDeleted?'':`<div class="trow payment-row">${person(t)}<span>${t.periodLabel||'Bu ay'}</span><span class="amount">${cash(t.rent)}</span><span>${t.dueLabel||`${t.day}. gün`}</span>${status(t.payment)}<button class="receipt-request-btn" data-index="${i}">${t.receiptRequested?'Talep edildi':'Dekont iste'}</button></div>`).join('');
  document.querySelectorAll('#tenantTableRows .more-row').forEach((x,i)=>x.outerHTML=`<button class="row-action terminate" data-index="${i}">Fesih</button>`);document.querySelectorAll('#paymentTableRows .payment-row').forEach((row,i)=>{row.insertAdjacentHTML('beforeend',`<span class="payment-actions"><button class="row-action paid" data-index="${i}">Ödendi</button><button class="row-action delete-payment" data-index="${i}">Sil</button></span>`)});
  if(!tenants.length){document.querySelectorAll('.metric-card h2').forEach((x,i)=>x.innerHTML=i===0||i===2?'₺0':i===1?'0 <span>kişi</span>':'0 <span>sözleşme</span>');document.querySelector('.chart-summary b').textContent='₺0';document.querySelector('.payment-timeline').innerHTML='<p class="empty-approval">Bugün planlanmış ödeme bulunmuyor.</p>';const contractRow=document.querySelector('.contract-panel .contract-row');if(contractRow)contractRow.parentElement.querySelectorAll('.contract-row').forEach(x=>x.remove());$('dueTenantList').innerHTML='<p class="empty-approval">Ödeme bekleyen kiracı bulunmuyor.</p>'}
}
