$('tenantTableRows').addEventListener('click',e=>{let b=e.target.closest('.terminate');if(!b)return;let t=tenants[+b.dataset.index],note=window.prompt(`${t.name} için erken fesih notu girin:`, 'Erken çıkış talebi');if(note===null)return;t.terminated=true;t.terminationNote=note;t.payment='Feshedildi';saveTenants();render();localStorage.setItem('kiraPanelLatestNotice',`${t.name}: sözleşme feshi kaydedildi.`);toast('Sözleşme feshi kaydedildi, kiracıya bildirim oluşturuldu.')});
$('paymentTableRows').addEventListener('click',e=>{let paid=e.target.closest('.paid'),del=e.target.closest('.delete-payment'),b=paid||del;if(!b)return;let t=tenants[+b.dataset.index];if(paid){t.payment='Ödendi';localStorage.setItem('kiraPanelLatestNotice',`${t.name}: kira ödemeniz onaylandı.`);toast('Kira ödendi olarak işaretlendi ve bildirim oluşturuldu.')}else{if(!window.confirm(`${t.name} için bu ödeme kaydı silinsin mi?`))return;t.paymentDeleted=true;toast('Ödeme kaydı silindi.')}saveTenants();render()});
function contractRenewalNotices(){let today=Date.now();tenants.forEach(t=>{if(!t.contractEnd)return;let days=Math.ceil((new Date(t.contractEnd).getTime()-today)/86400000);if(days>=0&&days<=30)localStorage.setItem('kiraPanelRenewalNotice',`${t.name}: sözleşme yenilemesine ${days} gün kaldı.`)})}contractRenewalNotices();
