function enterPortal(session){const role=session.role==='tenant'?'tenant':'agent';$('authScreen').classList.add('hidden');document.querySelector('.app-shell').hidden=role==='tenant';$('tenantPortal').hidden=role!=='tenant';if(role==='agent'){const managerName=(session.contact||'Yönetici').split('@')[0];$('accountName').textContent=managerName;const welcome=$('welcomeTitle');if(welcome)welcome.innerHTML=`Hoş geldiniz, ${managerName} <span>👋</span>`;loadAdminData()}else syncTenantPortal()}
function logout(){localStorage.removeItem('kiraPanelSession');localStorage.removeItem('kiraPanelApiToken');$('authScreen').classList.remove('hidden');document.querySelector('.app-shell').hidden=false;$('tenantPortal').hidden=true;showStep('contact');$('contactInput').value=''}
document.querySelectorAll('.role-choice').forEach(b=>b.addEventListener('click',()=>{auth.role=b.dataset.role;localStorage.setItem('kiraPanelPendingRole',auth.role);document.querySelectorAll('.role-choice').forEach(x=>x.classList.toggle('active',x===b))}));
document.querySelectorAll('.method').forEach(b=>b.addEventListener('click',()=>{auth.method=b.dataset.method;document.querySelectorAll('.method').forEach(x=>x.classList.toggle('active',x===b));let isMail=auth.method==='email';$('contactInput').type=isMail?'email':'tel';$('contactInput').placeholder=isMail?'ornek@firma.com':'05XX XXX XX XX';$('contactLabel').childNodes[0].nodeValue=isMail?'E-posta adresi':'Telefon numarası';$('contactHint').textContent=isMail?'Size 6 haneli bir doğrulama kodu göndereceğiz.':'Telefonunuza SMS ile 6 haneli doğrulama kodu göndereceğiz.'}));
function countdown(){let end=Date.now()+60000;clearInterval(auth.timer);auth.timer=setInterval(()=>{let s=Math.max(0,Math.ceil((end-Date.now())/1000));$('resendCode').innerHTML=s?`Kodu tekrar gönder <b>00:${String(s).padStart(2,'0')}</b>`:'Kodu tekrar gönder';if(!s)clearInterval(auth.timer)},1000)}
async function sendCode(){let contact=$('contactInput').value.trim(),valid=auth.method==='email'?emailOk(contact):phoneOk(contact);if(!valid)throw Error('Geçerli bir iletişim bilgisi girin.');auth.contact=contact;if(location.protocol==='file:'){auth.code=String(Math.floor(100000+Math.random()*900000));auth.expires=Date.now()+600000;$('devCode').hidden=false;$('devCode').textContent='Geliştirme kodu: '+auth.code}else{let r=await fetch('/api/auth/request-code',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({method:auth.method,contact})}),d=await r.json();if(!r.ok)throw Error(d.error);auth.code=d.debugCode||'';auth.expires=Date.now()+600000;$('devCode').hidden=!d.debugCode;$('devCode').textContent=d.debugCode?'Geliştirme kodu: '+d.debugCode:''}$('codeDescription').textContent=`${auth.method==='email'?'E-posta adresinize':'Telefon numaranıza'} gönderilen 6 haneli kodu girin.`;document.querySelectorAll('.code-inputs input').forEach(x=>x.value='');showStep('code');countdown()}
$('authForm').addEventListener('submit',async e=>{e.preventDefault();try{await sendCode()}catch(err){$('contactHint').textContent=err.message;$('contactHint').style.color='#d97665'}});$('backToContact').onclick=()=>showStep('contact');$('resendCode').onclick=()=>{if(!$('resendCode').textContent.includes('00:'))sendCode().catch(err=>toast(err.message))};
const digits=[...document.querySelectorAll('.code-inputs input')];function fillVerificationCode(raw){let code=String(raw||'').replace(/\D/g,'').slice(0,6);code.split('').forEach((digit,index)=>digits[index].value=digit);for(let index=code.length;index<digits.length;index++)digits[index].value='';(digits[Math.min(code.length,5)]||digits[0]).focus()}digits.forEach((x,i)=>{x.addEventListener('input',()=>{x.value=x.value.replace(/\D/g,'').slice(0,1);if(x.value&&i<5)digits[i+1].focus()});x.addEventListener('keydown',e=>{if(e.key==='Backspace'&&!x.value&&i)digits[i-1].focus()})});$('codeInputs').addEventListener('paste',event=>{event.preventDefault();fillVerificationCode(event.clipboardData?.getData('text')||'')});
$('verifyCode').addEventListener('click',async()=>{let code=digits.map(x=>x.value).join('');try{if(code.length!==6)throw Error('6 haneli kodu eksiksiz girin.');let verifiedRole=auth.role;if(location.protocol==='file:'){if(Date.now()>auth.expires||code!==auth.code)throw Error('Kod hatalı veya süresi doldu.')}else{let r=await fetch('/api/auth/verify-code',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({method:auth.method,contact:auth.contact,code})}),d=await r.json();if(!r.ok)throw Error(d.error);if(!d.token||!d.role)throw Error('Giriş oturumu oluşturulamadı. Lütfen kodu yeniden isteyin.');localStorage.setItem('kiraPanelApiToken',d.token);verifiedRole=d.role}let session={contact:auth.contact,role:verifiedRole,createdAt:Date.now()};localStorage.setItem('kiraPanelSession',JSON.stringify(session));enterPortal(session);toast('Doğrulama başarılı. Hoş geldiniz!')}catch(err){digits.forEach(x=>x.style.borderColor='#df806a');setTimeout(()=>digits.forEach(x=>x.style.borderColor=''),700);toast(err.message)}});
