const developmentLogin=document.createElement('button');developmentLogin.type='button';developmentLogin.id='developmentLogin';developmentLogin.className='resend development-login';developmentLogin.hidden=true;developmentLogin.textContent='Geliştirme koduyla giriş yap';$('devCode').after(developmentLogin);const baseSendCode=sendCode;sendCode=async function(){await baseSendCode();developmentLogin.hidden=!auth.code};developmentLogin.onclick=()=>{if(!auth.code)return;fillVerificationCode(auth.code);$('verifyCode').click()};
