const oldContractEndField=$('endInput').closest('label');oldContractEndField.hidden=true;const contractTerms=document.createElement('div');contractTerms.className='form-grid contact-grid';contractTerms.innerHTML='<label>Sözleşme başlangıcı<input id="contractStart" type="date" required /></label><label>Sözleşme süresi<select id="contractMonths" required><option value="6">6 aylık</option><option value="12" selected>1 yıllık</option><option value="24">2 yıllık</option></select></label><small class="contact-rule">Yenileme tarihi seçtiğiniz başlangıç ve süreye göre otomatik hesaplanır: <b id="renewalPreview">—</b></small>';paymentField.before(contractTerms);$('contractStart').value=new Date().toISOString().slice(0,10);function updateRenewalPreview(){let start=$('contractStart').value,months=+$('contractMonths').value;if(!start||!months)return;$('endInput').value=start;let d=new Date(`${start}T12:00:00`),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+months);let last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,last));let renewal=d.toISOString().slice(0,10);$('renewalPreview').textContent=new Date(`${renewal}T12:00:00`).toLocaleDateString('tr-TR',{day:'numeric',month:'long',year:'numeric'});$('endInput').value=renewal}['change','input'].forEach(event=>{$('contractStart').addEventListener(event,updateRenewalPreview);$('contractMonths').addEventListener(event,updateRenewalPreview)});updateRenewalPreview();
