const baseProfileLoader=loadTenantProfile;loadTenantProfile=async function(){await baseProfileLoader();let token=localStorage.getItem('kiraPanelApiToken');if(!token)return;try{let r=await tenantCreateFetch('/api/portal',{headers:{Authorization:'Bearer '+token}}),data=await r.json(),p=data.profile;if(!p)return;let end=new Date(`${p.contract_end}T12:00:00`),due=new Date(`${p.due_date}T12:00:00`),days=Math.max(0,Math.ceil((end-Date.now())/86400000));document.querySelector('.contract-badge').innerHTML=`Yenileme tarihine <b>${days} gün</b>`;document.querySelectorAll('.tenant-card p')[1].textContent=`Yenileme tarihi: ${end.toLocaleDateString('tr-TR')}`;document.querySelector('.rent-card p').innerHTML=`Son ödeme günü: <b>${due.toLocaleDateString('tr-TR')}</b>`;document.querySelector('.payment-description b').textContent=`${p.property.toUpperCase()} · ${p.due_date.slice(0,7)} KİRA BEDELİ`;let avatar=$('tenantLogout').querySelector('.avatar'),nameBox=$('tenantLogout').querySelector('b');if(avatar)avatar.textContent=p.name.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase();if(nameBox)nameBox.textContent=p.name;if(due<Date.now()&&p.status==='Bekliyor'){$('tenantPaymentStatus').textContent='Ödeme gecikti';$('tenantPaymentStatus').className='status overdue'}}catch(e){console.warn('Profile details unavailable',e)}};
