function addOperationsModules(){let overview=$('overview'),tenantMain=document.querySelector('.tenant-main');if(!$('announcementManager')){let a=document.createElement('article');a.id='announcementManager';a.className='panel ticket-panel';a.innerHTML='<div class="panel-header"><div><h3>Duyuru merkezi</h3><p>Kiracılara tek yerden bilgilendirme gönderin.</p></div></div><div class="ticket-form"><input id="announcementTitle" placeholder="Duyuru başlığı" /><textarea id="announcementText" maxlength="500" placeholder="Duyuru metni"></textarea><button id="publishAnnouncement" class="upload-receipt">Duyuruyu yayınla</button></div><div id="announcementList"></div>';overview.appendChild(a);$('publishAnnouncement').onclick=()=>{let title=$('announcementTitle').value.trim(),text=$('announcementText').value.trim();if(!title||!text)return toast('Duyuru başlığı ve metni girin.');let list=notices();list.unshift({id:Date.now(),title,text,date:new Date().toLocaleDateString('tr-TR')});saveNotices(list);$('announcementTitle').value='';$('announcementText').value='';renderAnnouncements();toast('Duyuru tüm kiracılara yayınlandı.')};}if(!$('tenantAnnouncements')&&tenantMain){let a=document.createElement('article');a.id='tenantAnnouncements';a.className='tenant-panel history-panel';a.innerHTML='<div class="panel-header"><div><h3>Duyurular</h3><p>Yöneticinizden güncellemeler</p></div></div><div id="tenantAnnouncementList"></div>';tenantMain.appendChild(a)}if(!$('bankMatchPanel')){let b=document.createElement('article');b.id='bankMatchPanel';b.className='panel ticket-panel';b.innerHTML='<div class="panel-header"><div><h3>Havale eşleştirme</h3><p>Banka hareketini kira ödemesiyle manuel eşleştirin.</p></div></div><div class="ticket-form"><input id="bankReference" placeholder="Havale açıklaması / referansı" /><input id="bankAmount" type="number" placeholder="Tutar (₺)" /><button id="addBankMatch" class="upload-receipt">Hareketi eşleştir</button></div><div id="bankMatchList"></div>';$('payments').appendChild(b);$('addBankMatch').onclick=()=>{let ref=$('bankReference').value.trim(),amount=+$('bankAmount').value;if(!ref||!amount)return toast('Havale açıklaması ve tutar girin.');let list=JSON.parse(localStorage.getItem('kiraPusulaBankMatches')||'[]');list.unshift({ref,amount,date:new Date().toLocaleDateString('tr-TR')});localStorage.setItem('kiraPusulaBankMatches',JSON.stringify(list));$('bankReference').value='';$('bankAmount').value='';renderBankMatches();toast('Havale hareketi eşleştirildi.')};}renderAnnouncements();renderBankMatches()}
