// Keep shared operational data on the server. Local storage remains only as an
// offline display cache, so a tenant and manager can use separate devices.
async function operationRequest(url,method='GET',body){let token=localStorage.getItem('kiraPanelApiToken');if(!token)return null;let r=await tenantCreateFetch(url,{method,headers:{Authorization:'Bearer '+token,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});if(!r.ok)throw Error((await r.json()).error||'İşlem gerçekleştirilemedi.');return r.json()}
async function syncOperations(){try{let [a,t]=await Promise.all([operationRequest('/api/announcements'),operationRequest('/api/tickets')]);if(a){saveNotices(a.items.map(x=>({id:x.id,title:x.title,text:x.body,date:new Date(x.created_at).toLocaleDateString('tr-TR')})));renderAnnouncements()}if(t){saveTickets(t.items);renderTickets()}let session=JSON.parse(localStorage.getItem('kiraPanelSession')||'{}');if(session.role==='agent'){let b=await operationRequest('/api/bank-matches');if(b){localStorage.setItem('kiraPusulaBankMatches',JSON.stringify(b.items.map(x=>({id:x.id,ref:x.reference,amount:x.amount,date:new Date(x.created_at).toLocaleDateString('tr-TR')}))));renderBankMatches()}}}catch(e){console.warn('Operations could not sync',e)}}

// Upgrade the original simple inbox with a complete, visible workflow.
const basicTicketRender=renderTickets;renderTickets=function(){basicTicketRender();let rows=[...document.querySelectorAll('#managerTicketPanel .ticket-row')],list=tickets();rows.forEach((row,i)=>{let t=list[i],actions=row.querySelector('.ticket-actions');if(!t||!actions)return;let label=t.status||'Yeni';if(label!=='Yeni'){actions.innerHTML=`<span class="ticket-status ${label==='İşlemde'?'processing':label==='Çözüldü'?'resolved':''}">${label}</span>`}if(label!=='Çözüldü'){let processing=document.createElement('button');processing.className='row-action processing';processing.dataset.ticketStatus='İşlemde';processing.dataset.ticketId=t.id;processing.textContent='İşlemde';let resolved=document.createElement('button');resolved.className='row-action resolved';resolved.dataset.ticketStatus='Çözüldü';resolved.dataset.ticketId=t.id;resolved.textContent='Çözüldü';actions.append(processing,resolved)}})};
$('managerTicketPanel').addEventListener('click',async e=>{let b=e.target.closest('[data-ticket-status]');if(!b)return;let list=tickets(),t=list.find(x=>x.id===+b.dataset.ticketId);if(!t)return;t.status=b.dataset.ticketStatus;saveTickets(list);renderTickets();try{await operationRequest('/api/tickets','POST',{id:t.id,status:t.status});toast(`Bildirim ${t.status.toLocaleLowerCase('tr')} olarak güncellendi.`)}catch(err){toast(err.message)}});

