$('sendTicket').onclick=async()=>{let message=$('ticketMessage').value.trim(),type=$('ticketType').value;if(!message)return toast('Lütfen kısa bir açıklama yazın.');try{await operationRequest('/api/tickets','POST',{type,message});$('ticketMessage').value='';await syncOperations();toast('Bildirim yönetici paneline gönderildi.')}catch(e){toast(e.message)}};
