// The manager view always reflects the same SQLite records used by the tenant portal.
function dateLabel(value){if(!value)return '—';return new Intl.DateTimeFormat(localeTag(),{day:'numeric',month:'short',year:'numeric'}).format(new Date(`${value}T12:00:00`))}
async function loadAdminData(){let token=localStorage.getItem('kiraPanelApiToken');if(!token)return;try{let response=await fetch('/api/tenants',{headers:{Authorization:'Bearer '+token}});if(!response.ok)return;let data=await response.json();tenants=data.items.map((x,i)=>{let code=x.payment_status_code||'PENDING',payment={PAID:'Ödendi',TERMINATED:'Feshedildi',DELETED:'Silindi',RECEIPT_UPLOADED:'Dekont yüklendi',PENDING:'Bekliyor'}[code]||'Bekliyor';return{id:x.id,name:x.name,phone:x.contact||'',address:x.address||'',owner:x.owner_name||'',initials:x.name.split(' ').filter(Boolean).map(w=>w[0]).join('').slice(0,2).toLocaleUpperCase(localeTag()),property:x.property,rent:x.rent,day:x.payment_day,contractStart:x.contract_start,contractEnd:x.contract_end,contractDurationDays:x.contract_duration_days,rentalCategory:x.rental_category,payment,paymentCode:code,status:code==='PAID'?'Ödendi':x.due_date&&new Date(`${x.due_date}T23:59:59`)<new Date()?'Gecikmiş':'Bekliyor',receiptRequested:!!x.receipt_required,period:x.period,dueDate:x.due_date,periodLabel:x.period?new Intl.DateTimeFormat(localeTag(),{month:'long',year:'numeric'}).format(new Date(`${x.period}-01T12:00:00`)):'',dueLabel:dateLabel(x.due_date),color:['av1','av2',''][i%3]}});saveTenants();render();let paid=tenants.filter(t=>t.paymentCode==='PAID'||t.payment==='Ödendi').reduce((sum,t)=>sum+t.rent,0),expected=tenants.reduce((sum,t)=>sum+t.rent,0),remaining=expected-paid,near=tenants.filter(t=>{let d=(new Date(`${t.contractEnd}T23:59:59`)-Date.now())/86400000;return d>=0&&d<=30}).length,metrics=[...document.querySelectorAll('.metric-card h2')];if(metrics.length>=4){metrics[0].textContent=cash(paid);metrics[1].innerHTML=`${tenants.length} <span>kişi</span>`;metrics[2].textContent=cash(remaining);metrics[3].innerHTML=`${near} <span>sözleşme</span>`}document.querySelector('.chart-summary b').textContent=cash(paid);let summary=[...document.querySelectorAll('.payment-summary b')];if(summary.length===3){summary[0].textContent=cash(expected);summary[1].textContent=cash(paid);summary[2].textContent=cash(remaining)}$('tenantCount').textContent=tenants.length;$('activeTenantNum').innerHTML=`${tenants.length} <span>kişi</span>`}catch(error){console.warn('Manager data could not load',error)}}

