contractTerms.innerHTML='<label>Sözleşme başlangıcı<input id="contractStart" type="date" required /></label><label>Sözleşme bitişi<input id="contractEndManual" type="date" required /></label><small class="contact-rule">Sözleşme süresi: <b id="durationPreview">—</b></small><aside id="shortStayNotice" class="short-stay-notice" hidden></aside>';let previousStart=$('contractStart').value||new Date().toISOString().slice(0,10);$('contractStart').value=previousStart;let defaultEnd=new Date(`${previousStart}T12:00:00`);defaultEnd.setFullYear(defaultEnd.getFullYear()+1);$('contractEndManual').value=defaultEnd.toISOString().slice(0,10);function updateManualDuration(){let start=$('contractStart').value,end=$('contractEndManual').value;if(!start||!end)return;let days=Math.round((new Date(`${end}T12:00:00`)-new Date(`${start}T12:00:00`))/86400000),preview=$('durationPreview'),notice=$('shortStayNotice');if(days<1){preview.textContent='Bitiş tarihi başlangıçtan sonra olmalı';notice.hidden=true;return}let months=Math.floor(days/30),years=(days/365).toFixed(1).replace('.',',');preview.textContent=`${days} gün · yaklaşık ${months} ay (${years} yıl)`;$('endInput').value=end;if(days<=100){notice.hidden=false;notice.innerHTML='<b>⏱ Kısa dönem kiralama uyarısı</b><span>100 gün ve altı süreler turizm amaçlı kiralama kapsamına girebilir. İzin belgesi, plaket ve bina/kat maliki onayı gibi şartları resmi kaynaklardan kontrol edin. Konaklama tesisi niteliğinde ise KBS yükümlülüğünü de doğrulayın.</span><a href="https://yigm.ktb.gov.tr/TR-436391/turizm-amacli-konutlar.html" target="_blank" rel="noreferrer">Resmî başvuru bilgileri ↗</a>'}else{notice.hidden=false;notice.classList.add('long-stay');notice.innerHTML='<b>✓ Uzun dönem kira kaydı</b><span>101 gün üzerindeki süre için turizm amaçlı kısa dönem izin akışı tetiklenmez. Sözleşmenizin ve taşınmazınızın özel koşullarını ayrıca kontrol edin.</span>';}}$('contractStart').addEventListener('change',updateManualDuration);$('contractEndManual').addEventListener('change',updateManualDuration);updateManualDuration();
