function buildPasswordAuthentication(){let form=$('authForm');form.innerHTML='<div class="auth-step active password-auth"><span class="eyebrow">PUSULAKİRA’YA HOŞ GELDİNİZ</span><h2 id="passwordAuthTitle">Yönetici girişi</h2><p id="passwordAuthDescription">Yönetici hesabınızla portföyünüzü yönetin.</p><div class="role-picker"><button type="button" class="role-choice active" data-password-role="agent"><b>Yönetici</b><small>Portföy, kiracı ve tahsilat yönetimi</small></button><button type="button" class="role-choice" data-password-role="tenant"><b>Kiracı</b><small>Kira ve sözleşme takibi</small></button></div><div id="managerMode" class="method-toggle"><button type="button" class="method active" data-manager-mode="login">Giriş yap</button><button type="button" class="method" data-manager-mode="register">Kayıt ol</button></div><label>Ad soyad<input id="passwordAuthName" required autocomplete="name" placeholder="Örn. Ayşe Demir" /></label><label>Parola<input id="passwordAuthPassword" required type="password" minlength="6" autocomplete="current-password" placeholder="En az 6 karakter" /></label><label id="passwordConfirmLabel" hidden>Parola tekrarı<input id="passwordAuthConfirm" type="password" minlength="6" autocomplete="new-password" placeholder="Parolanızı tekrar yazın" /></label><button class="auth-primary" type="submit" id="passwordAuthSubmit">Giriş yap <span>→</span></button><p id="passwordAuthFeedback" class="field-note" aria-live="polite"></p><div class="auth-security-note"><b>✓</b><span>Bu cihazda 30 gün boyunca oturumunuz açık kalır.</span></div></div>';let role='agent',mode='login',feedback=$('passwordAuthFeedback');function renderPasswordAuth(){let manager=role==='agent';$('passwordAuthTitle').textContent=manager?(mode==='register'?'Yönetici hesabı oluştur':'Yönetici girişi'):'Kiracı girişi';$('passwordAuthDescription').textContent=manager?(mode==='register'?'Adınız ve parolanızla yönetici hesabınızı oluşturun.':'Ad soyadınız ve parolanızla giriş yapın.'):'Yöneticinizin verdiği ad soyad ve parola ile giriş yapın.';$('managerMode').hidden=!manager;$('passwordConfirmLabel').hidden=!(manager&&mode==='register');$('passwordAuthPassword').autocomplete=manager&&mode==='register'?'new-password':'current-password';$('passwordAuthSubmit').innerHTML=manager&&mode==='register'?'Hesabı oluştur <span>→</span>':'Giriş yap <span>→</span>';feedback.textContent=''}form.querySelectorAll('[data-password-role]').forEach(button=>button.onclick=()=>{role=button.dataset.passwordRole;form.querySelectorAll('[data-password-role]').forEach(item=>item.classList.toggle('active',item===button));renderPasswordAuth()});form.querySelectorAll('[data-manager-mode]').forEach(button=>button.onclick=()=>{mode=button.dataset.managerMode;form.querySelectorAll('[data-manager-mode]').forEach(item=>item.classList.toggle('active',item===button));renderPasswordAuth()});form.addEventListener('submit',async event=>{event.preventDefault();let name=$('passwordAuthName').value.trim(),password=$('passwordAuthPassword').value,confirm=$('passwordAuthConfirm').value,isManager=role==='agent';if(isManager&&mode==='register'&&password!==confirm){feedback.textContent='Parolalar aynı değil.';return}let submit=$('passwordAuthSubmit');submit.disabled=true;feedback.textContent='İşleminiz doğrulanıyor…';try{let path=isManager&&mode==='register'?'/api/auth/register-manager':'/api/auth/login',payload=isManager&&mode==='register'?{name,password}:{role,name,password},response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)throw Error(data.error||'Giriş yapılamadı.');localStorage.setItem('kiraPanelApiToken',data.token);let session={contact:data.name||name,role:data.role,createdAt:Date.now()};localStorage.setItem('kiraPanelSession',JSON.stringify(session));enterPortal(session)}catch(error){feedback.textContent=error.message}finally{submit.disabled=false}});renderPasswordAuth()}buildPasswordAuthentication();function passwordLogout(){localStorage.removeItem('kiraPanelSession');localStorage.removeItem('kiraPanelApiToken');$('authScreen').classList.remove('hidden');document.querySelector('.app-shell').hidden=false;$('tenantPortal').hidden=true;buildPasswordAuthentication()}$('profileBtn').onclick=passwordLogout;$('tenantLogout').onclick=passwordLogout;
document.addEventListener('submit',event=>{if(event.target.id==='authForm'){let selected=event.target.querySelector('[data-password-role].active');auth.role=selected?.dataset.passwordRole||'agent'}},true);
