function buildManagerSections(){let contracts=$('contracts'),properties=$('properties'),reports=$('reports'),settings=$('settings');[contracts,properties,reports,settings].forEach(page=>{page.classList.remove('empty-page');page.classList.add('data-page')});contracts.innerHTML='<div class="page-heading"><div><h1>Sözleşmeler</h1><p>Aktif, yaklaşan ve feshedilen kira sözleşmelerini takip edin.</p></div></div><article class="panel table-panel contract-table"><div class="tenant-table"><div class="thead"><span>Kiracı</span><span>Gayrimenkul</span><span>Yenileme tarihi</span><span>Durum</span></div><div id="contractRows"></div></div></article>';properties.innerHTML='<div class="page-heading"><div><h1>Gayrimenkuller</h1><p>Portföyünüzdeki kiralanabilir alanlar.</p></div></div><article class="panel table-panel"><div class="tenant-table"><div class="thead"><span>Gayrimenkul</span><span>Ev sahibi</span><span>Aylık kira</span><span>Kiracı</span><span></span><span></span></div><div id="propertyRows"></div></div></article>';reports.innerHTML='<div class="page-heading"><div><h1>Raporlar</h1><p>Bu ayın tahsilat görünümü.</p></div></div><div id="reportKpis" class="report-kpis"></div><article class="panel"><div class="panel-header"><div><h3>Rapor özeti</h3><p>Mevcut kira kayıtlarından hesaplanır.</p></div></div><p id="reportText" class="property-meta"></p></article>';settings.innerHTML='<div class="page-heading"><div><h1>Ayarlar</h1><p>Bildirim ve çalışma tercihlerinizi düzenleyin.</p></div></div><div class="settings-grid"><article class="panel"><div class="panel-header"><div><h3>Bildirim tercihleri</h3><p>Bu cihazdaki hatırlatma tercihleri.</p></div></div><label class="setting-row"><span><b>Ödeme hatırlatmaları</b><small>Vadesi yaklaşan kiralar için uyarı göster.</small></span><input id="paymentPreference" type="checkbox" checked></label><label class="setting-row"><span><b>Sözleşme uyarıları</b><small>Yenilemeye 30 gün kala yöneticiye bildir.</small></span><input id="contractPreference" type="checkbox" checked></label></article><article class="panel"><div class="panel-header"><div><h3>Hesap durumu</h3><p>Canlıya geçişten önce kontrol listesi.</p></div></div><div class="setting-row"><span><b>Giriş doğrulama</b><small>Yerel geliştirme kodu ile aktif.</small></span><span class="ticket-status">Aktif</span></div><div class="setting-row"><span><b>Otomatik banka entegrasyonu</b><small>Sağlayıcı hesabı bağlanınca açılır.</small></span><span class="ticket-status">Bekliyor</span></div></article></div>';let savePreference=()=>localStorage.setItem('pusulaKiraPreferences',JSON.stringify({payment:$('paymentPreference').checked,contract:$('contractPreference').checked}));let prefs=JSON.parse(localStorage.getItem('pusulaKiraPreferences')||'{"payment":true,"contract":true}');$('paymentPreference').checked=prefs.payment;$('contractPreference').checked=prefs.contract;$('paymentPreference').onchange=savePreference;$('contractPreference').onchange=savePreference}
function refreshManagerSections(){if(!$('contractRows'))return;let active=tenants.filter(t=>t.payment!=='Feshedildi'),expected=active.reduce((sum,t)=>sum+t.rent,0),paid=active.filter(t=>t.payment==='Ödendi').reduce((sum,t)=>sum+t.rent,0),waiting=active.filter(t=>!['Ödendi','Silindi'].includes(t.payment));$('contractRows').innerHTML=tenants.length?tenants.map(t=>`<div class="trow"><span class="person"><span class="avatar ${t.color}">${t.initials}</span><b>${t.name}</b></span><span class="property-text">${t.property}</span><span><b>${dateLabel(t.contractEnd)}</b><small>${t.contractDurationDays?`${t.contractDurationDays} gün · ${t.rentalCategory||'Sözleşme'}`:'Sözleşme süresi eski kayıtta yok'}</small></span>${status(t.payment==='Feshedildi'?'Feshedildi':t.contractEnd&&new Date(`${t.contractEnd}T23:59:59`)-Date.now()<30*86400000?'Yaklaşıyor':'Aktif')}</div>`).join(''):'<p class="ticket-empty">Henüz sözleşme kaydı yok.</p>';$('propertyRows').innerHTML=tenants.length?tenants.map(t=>`<div class="trow"><span class="property-text">${t.property}</span><span class="property-meta">Ev sahibi</span><span class="amount">${cash(t.rent)}</span><span>${t.name}</span><span></span><span></span></div>`).join(''):'<p class="ticket-empty">Henüz gayrimenkul kaydı yok.</p>';$('reportKpis').innerHTML=`<article class="report-kpi"><span>Beklenen</span><b>${cash(expected)}</b></article><article class="report-kpi"><span>Tahsil edilen</span><b>${cash(paid)}</b></article><article class="report-kpi"><span>Bekleyen</span><b>${cash(expected-paid)}</b></article>`;$('reportText').textContent=waiting.length?`${waiting.length} kiracının bu ay ödemesi bekleniyor.`:'Bu ay bekleyen ödeme bulunmuyor.';let timeline=document.querySelector('.payment-timeline');if(timeline)timeline.innerHTML=waiting.length?waiting.slice(0,3).map(t=>`<div class="timeline-item"><span class="time">${t.day}. gün</span><div class="timeline-card purple"><b>${t.property}</b><small>${t.name} · ${cash(t.rent)}</small></div></div>`).join(''):'<div class="dashboard-empty schedule-empty"><i data-icon="calendar"></i><span>Bu hafta planlanmış ödeme bulunmuyor.</span></div>';let card=document.querySelector('.contract-panel');if(card){let rows=tenants.filter(t=>t.contractEnd).sort((a,b)=>new Date(a.contractEnd)-new Date(b.contractEnd)).slice(0,2);card.querySelectorAll('.contract-row').forEach(x=>x.remove());rows.forEach(t=>{let days=Math.max(0,Math.ceil((new Date(`${t.contractEnd}T23:59:59`)-Date.now())/86400000));card.querySelector('.contract-action').insertAdjacentHTML('beforebegin',`<div class="contract-row"><div class="avatar ${t.color}">${t.initials}</div><div><b>${t.name}</b><small>${t.property}</small></div><div class="days"><b>${days} gün</b><small>${dateLabel(t.contractEnd)}</small></div></div>`)});if(!rows.length)card.querySelector('.contract-action').insertAdjacentHTML('beforebegin','<p class="ticket-empty">Yaklaşan sözleşme bulunmuyor.</p>')}}
buildManagerSections();const completeAdminLoader=loadAdminData;loadAdminData=async function(){await completeAdminLoader();refreshManagerSections()};if(JSON.parse(localStorage.getItem('kiraPanelSession')||'null')?.role==='agent')loadAdminData();
document.querySelector('.auth-step .eyebrow').textContent='PUSULAKİRA’YA HOŞ GELDİNİZ';
const legacyTerms=document.querySelector('.auth-step[data-step="contact"] .terms');if(legacyTerms){const authSecurityNote=document.createElement('div');authSecurityNote.className='auth-security-note';authSecurityNote.innerHTML='<b>✓</b><span>6 haneli doğrulama koduyla güvenli giriş</span>';legacyTerms.before(authSecurityNote)}

// Apartment-management foundation: sites, blocks, units and a visible audit trail.
async function managerApi(path, method='GET', payload){let token=localStorage.getItem('kiraPanelApiToken');let response=await fetch(path,{method,headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:payload?JSON.stringify(payload):undefined});let data=await response.json();if(!response.ok)throw Error(data.error||'İşlem gerçekleştirilemedi.');return data}
async function refreshSiteManagement(){let panel=$('siteManagementPanel');if(!panel)return;try{let data=await managerApi('/api/site-structure'),siteOptions=data.sites.map(site=>`<option value="${site.id}">${site.name}</option>`).join(''),blockOptions=data.blocks.map(block=>{let site=data.sites.find(item=>item.id===block.site_id);return `<option value="${block.id}">${site?.name||'Site'} · ${block.name}</option>`}).join('');panel.innerHTML=`<div class="panel-header"><div><h3>Site, blok ve daire yapısı</h3><p>Apartman yönetimi için yapınızı kurun; kira kayıtları ayrı olarak korunur.</p></div><span class="ticket-status">${data.units.length} daire</span></div><div class="structure-forms"><form id="siteCreateForm" class="ticket-form"><b>1. Site / bina</b><input id="siteName" required placeholder="Site veya bina adı"/><input id="siteAddress" placeholder="Adres (isteğe bağlı)"/><button class="upload-receipt">Site ekle</button></form><form id="blockCreateForm" class="ticket-form"><b>2. Blok</b><select id="blockSite" required><option value="">Site seçin</option>${siteOptions}</select><input id="blockName" required placeholder="Örn. A Blok"/><button class="upload-receipt">Blok ekle</button></form><form id="unitCreateForm" class="ticket-form"><b>3. Daire</b><select id="unitBlock" required><option value="">Blok seçin</option>${blockOptions}</select><input id="unitNo" required placeholder="Örn. 12"/><select id="unitOccupancy"><option>Boş</option><option>Dolu</option></select><button class="upload-receipt">Daire ekle</button></form></div><div class="structure-summary">${data.sites.length?data.sites.map(site=>{let blocks=data.blocks.filter(block=>block.site_id===site.id);let unitCount=blocks.reduce((sum,block)=>sum+data.units.filter(unit=>unit.block_id===block.id).length,0);return `<div><b>${site.name}</b><small>${blocks.length} blok · ${unitCount} daire${site.address?` · ${site.address}`:''}</small></div>`}).join(''):'<p class="ticket-empty">Henüz site/bina kaydı yok.</p>'}</div>`;let submit=(id,handler)=>$(id).addEventListener('submit',async event=>{event.preventDefault();try{await handler();await refreshSiteManagement();toast('Kayıt eklendi.')}catch(error){toast(error.message)}});submit('siteCreateForm',()=>managerApi('/api/site-structure','POST',{kind:'site',name:$('siteName').value.trim(),address:$('siteAddress').value.trim()}));submit('blockCreateForm',()=>managerApi('/api/site-structure','POST',{kind:'block',siteId:+$('blockSite').value,name:$('blockName').value.trim()}));submit('unitCreateForm',()=>managerApi('/api/site-structure','POST',{kind:'unit',blockId:+$('unitBlock').value,unitNo:$('unitNo').value.trim(),occupancy:$('unitOccupancy').value}));}catch(error){panel.innerHTML='<p class="ticket-empty">Yapı bilgileri yüklenemedi.</p>'}}
async function refreshAuditLog(){let target=$('auditLogList');if(!target)return;try{let data=await managerApi('/api/activity-logs');target.innerHTML=data.items.length?data.items.slice(0,12).map(item=>`<div class="audit-row"><div><b>${item.action}</b><small>${item.actor}${item.details?` · ${item.details}`:''}</small></div><time>${new Date(item.created_at).toLocaleString('tr-TR',{dateStyle:'short',timeStyle:'short'})}</time></div>`).join(''):'<p class="ticket-empty">Henüz kayıtlı işlem yok.</p>'}catch{target.innerHTML='<p class="ticket-empty">Sistem günlüğü yüklenemedi.</p>'}}
function mountSiteManagement(){let properties=$('properties'),settings=$('settings');if(properties&&!$('siteManagementPanel')){let panel=document.createElement('article');panel.id='siteManagementPanel';panel.className='panel ticket-panel site-management-panel';properties.appendChild(panel)}if(settings&&!$('auditLogPanel')){let panel=document.createElement('article');panel.id='auditLogPanel';panel.className='panel ticket-panel audit-log-panel';panel.innerHTML='<div class="panel-header"><div><h3>Sistem hareketleri</h3><p>Yönetici işlemleri ve takip kayıtları.</p></div></div><div id="auditLogList"></div>';settings.appendChild(panel)}refreshSiteManagement();refreshAuditLog()}
const previousManagerLoad=loadAdminData;loadAdminData=async function(){await previousManagerLoad();mountSiteManagement()};

// Remove every template value once a tenant signs in; only the authenticated record is displayed.
const lastTenantLoader=loadTenantProfile;loadTenantProfile=async function(){await lastTenantLoader();let token=localStorage.getItem('kiraPanelApiToken');if(!token)return;try{let response=await fetch('/api/portal',{headers:{Authorization:`Bearer ${token}`}}),data=await response.json(),p=data.profile;if(!response.ok||!p)return;let amount=$('.rent-card h2'),due=$('.rent-card p b'),welcome=$('.tenant-welcome h1'),profileName=$('.tenant-profile b'),iban=$('ibanText'),description=document.querySelector('.payment-description b'),statusNode=$('tenantPaymentStatus');if(amount)amount.textContent=cash(p.rent);if(due)due.textContent=new Date(`${p.due_date}T12:00:00`).toLocaleDateString('tr-TR');if(welcome)welcome.textContent=`Merhaba, ${p.name.split(' ')[0]} 👋`;if(profileName)profileName.textContent=p.name;if(iban)iban.textContent=p.iban||'Yönetici IBAN bilgisi eklemedi.';if(description)description.textContent=`${p.property} — ${new Date().toLocaleDateString('tr-TR',{month:'long',year:'numeric'}).toUpperCase('tr-TR')} KİRA BEDELİ`;if(statusNode)statusNode.textContent=p.status==='Ödendi'?'Ödeme onaylandı':p.status==='Dekont yüklendi'?'Dekont inceleniyor':'Ödeme bekleniyor'}catch(error){console.warn('Tenant data refresh failed',error)}};

// Hidden portal markup never exposes placeholder people or balances while the real profile is loading.
function clearTenantTemplate(){let portal=$('tenantPortal');if(!portal)return;let name=portal.querySelector('.tenant-profile b'),welcome=portal.querySelector('.tenant-welcome h1'),amount=portal.querySelector('.rent-card h2'),contract=portal.querySelectorAll('.tenant-card')[1],owner=portal.querySelectorAll('.tenant-card')[2];if(name)name.textContent='';if(welcome)welcome.textContent='Merhaba';if(amount)amount.textContent='₺0';if(contract){contract.querySelector('h3').textContent='Sözleşme bilgisi yükleniyor';contract.querySelector('p').textContent='';}if(owner){owner.querySelector('h3').textContent='Ev sahibi bilgisi yükleniyor';owner.querySelector('p').textContent='';}let history=portal.querySelector('.history-panel');if(history)history.innerHTML='<div class="panel-header"><div><h3>Ödeme geçmişi</h3><p>Doğrulanmış işlemleriniz burada görünür.</p></div></div><p class="empty-approval">Henüz doğrulanmış ödeme geçmişi yok.</p>';}clearTenantTemplate();

// Manager payment controls: receipts are opened through an authenticated API, never by a public upload URL.
document.querySelector('.workspace')?.remove();
document.querySelectorAll('#bankMatchPanel').forEach(panel=>panel.remove());
function renderReceiptButtons(){let rows=[...document.querySelectorAll('#paymentTableRows .payment-row')];rows.forEach((row,index)=>{let tenant=tenants[index];if(!tenant?.receiptName||row.querySelector('.view-receipt'))return;let button=document.createElement('button');button.className='row-action view-receipt';button.dataset.receipt=tenant.receiptName;button.textContent='Dekontu gör';let actions=row.querySelector('.payment-actions');if(actions)actions.prepend(button);else row.append(button)})}
async function openReceipt(name){try{let token=localStorage.getItem('kiraPanelApiToken'),response=await fetch(`/api/receipts/${encodeURIComponent(name)}`,{headers:{Authorization:`Bearer ${token}`}});if(!response.ok){let body=await response.json();throw Error(body.error||'Dekont açılamadı.')}let url=URL.createObjectURL(await response.blob());window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(error){toast(error.message)}}
$('paymentTableRows').addEventListener('click',event=>{let button=event.target.closest('.view-receipt');if(button)openReceipt(button.dataset.receipt)});
const receiptAwareAdminLoader=loadAdminData;loadAdminData=async function(){await receiptAwareAdminLoader();try{let token=localStorage.getItem('kiraPanelApiToken'),response=await fetch('/api/tenants',{headers:{Authorization:`Bearer ${token}`}}),data=await response.json();if(response.ok){let receipts=new Map(data.items.map(item=>[item.id,item.receipt_name]));tenants.forEach(tenant=>tenant.receiptName=receipts.get(tenant.id)||'');render();renderReceiptButtons()}}catch(error){console.warn('Receipt list could not refresh',error)}};

