oldContactPanel.style.display='grid';oldContactPanel.classList.add('phone-contact-panel');oldContactPanel.innerHTML='<label>Telefon numarası<input id="tenantPhoneInput" type="tel" required inputmode="tel" placeholder="05XX XXX XX XX" /></label><input id="tenantEmailInput" type="hidden" value="" /><small class="contact-rule">Kiracı ile iletişim ve kayıt takibi için telefon numarası zorunludur.</small>';
if(!$('addressInput')){let field=document.createElement('label');field.innerHTML='Açık adres<input id="addressInput" required maxlength="300" placeholder="Mahalle, cadde/sokak, bina ve daire bilgisi" />';$('propertyInput').closest('label').after(field)}
const addressPhoneFetch=window.fetch.bind(window);window.fetch=(url,options={})=>{if(url==='/api/tenants'&&options.body){try{let body=JSON.parse(options.body);body.phone=$('tenantPhoneInput')?.value.trim()||'';body.address=$('addressInput')?.value.trim()||'';body.contact=body.phone;options={...options,body:JSON.stringify(body)}}catch{}}return addressPhoneFetch(url,options)};

