// Final password-only submit gate. It prevents retired OTP listeners from intercepting current sign-ins.
document.addEventListener('submit',async event=>{let form=event.target;if(form.id!=='authForm'||!form.querySelector('.password-auth'))return;event.preventDefault();event.stopImmediatePropagation();let role=form.querySelector('[data-password-role].active')?.dataset.passwordRole||'agent',mode=form.querySelector('[data-manager-mode].active')?.dataset.managerMode||'login',name=$('passwordAuthName')?.value.trim()||'',password=$('passwordAuthPassword')?.value||'',confirm=$('passwordAuthConfirm')?.value||'',feedback=$('passwordAuthFeedback'),submit=$('passwordAuthSubmit'),creating=role==='agent'&&mode==='register';if(!name||!password){feedback.textContent='Ad soyad ve parola girin.';return}if(creating&&password!==confirm){feedback.textContent='Parolalar aynı değil.';return}submit.disabled=true;feedback.textContent='İşleminiz doğrulanıyor…';try{let response=await fetch(creating?'/api/auth/register-manager':'/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(creating?{name,password}:{role,name,password})}),data=await response.json();if(!response.ok)throw Error(data.error||'Giriş yapılamadı.');localStorage.setItem('kiraPanelApiToken',data.token);let session={contact:data.name||name,role:data.role,createdAt:Date.now()};localStorage.setItem('kiraPanelSession',JSON.stringify(session));enterPortal(session)}catch(error){feedback.textContent=error.message}finally{submit.disabled=false}},true);

// Keep the manager form in one predictable reading order on every screen size.
const previousContactDetails=$('tenantContactDetails');if(previousContactDetails)previousContactDetails.remove();document.querySelectorAll('#addressInput').forEach(input=>input.closest('label')?.remove());oldContactPanel.remove();let tenantContactDetails=document.createElement('div');tenantContactDetails.id='tenantContactDetails';tenantContactDetails.className='form-grid tenant-contact-details';tenantContactDetails.innerHTML='<label>Açık adres<input id="addressInput" required maxlength="300" placeholder="Mahalle, cadde/sokak, bina ve daire bilgisi" /></label><label>Telefon numarası<input id="tenantPhoneInput" type="tel" required inputmode="tel" placeholder="05XX XXX XX XX" /></label><input id="tenantEmailInput" type="hidden" value="" />';$('propertyInput').closest('label').after(tenantContactDetails);

// Compact, useful manager controls: payment actions stay in their own right column.
let selectedPaymentFilter='all';
function paymentIsApproaching(tenant){if(tenant.payment==='Ödendi'||tenant.payment==='Silindi'||tenant.payment==='Feshedildi')return false;let now=new Date(),due=new Date(now.getFullYear(),now.getMonth(),Number(tenant.day)||1);due.setHours(0,0,0,0);let today=new Date(now);today.setHours(0,0,0,0);if(due<today)due.setMonth(due.getMonth()+1);let days=Math.round((due-today)/86400000);return days>=0&&days<=3}
function applyPaymentFilter(){let rows=[...document.querySelectorAll('#paymentTableRows .payment-row')],query=($('paymentSearch')?.value||'').trim().toLocaleLowerCase('tr');rows.forEach(row=>{let tenant=tenants[Number(row.dataset.index)],filterMatch=selectedPaymentFilter==='all'||(selectedPaymentFilter==='approaching'?paymentIsApproaching(tenant):tenant?.payment===selectedPaymentFilter),searchMatch=!query||[tenant?.name,tenant?.property,tenant?.periodLabel,tenant?.dueLabel].filter(Boolean).join(' ').toLocaleLowerCase('tr').includes(query);row.hidden=!(filterMatch&&searchMatch)});let empty=$('paymentFilterEmpty');if(empty)empty.hidden=rows.some(row=>!row.hidden)}
const alignedPaymentRender=render;render=function(){alignedPaymentRender();let target=$('paymentTableRows');if(target){document.querySelectorAll('#paymentFilterEmpty').forEach(item=>item.remove());target.innerHTML=tenants.map((tenant,index)=>tenant.paymentDeleted?'':`<div class="trow payment-row" data-index="${index}">${person(tenant)}<span>${tenant.periodLabel||'Bu ay'}</span><span class="amount">${cash(tenant.rent)}</span><span>${tenant.dueLabel||`${tenant.day}. gün`}</span>${status(tenant.payment)}<span class="payment-actions"><button class="receipt-request-btn" data-index="${index}">${tenant.receiptRequested?'Dekont talebi açık':'Dekont iste'}</button><button class="row-action paid" data-index="${index}">Ödendi</button><button class="row-action delete-payment" data-index="${index}">Sil</button></span></div>`).join('')||'<p class="ticket-empty">Gösterilecek ödeme kaydı yok.</p>';target.insertAdjacentHTML('afterend','<p id="paymentFilterEmpty" class="ticket-empty" hidden>Bu filtreye uygun ödeme kaydı yok.</p>');applyPaymentFilter()}renderManagerPropertyContacts()};
function renderManagerPropertyContacts(){let rows=$('propertyRows');if(!rows)return;let header=rows.parentElement.querySelector('.thead');if(header)header.innerHTML='<span>Gayrimenkul</span><span>Ev sahibi</span><span>Aylık kira</span><span>Kiracı ve iletişim</span>';rows.innerHTML=tenants.length?tenants.map(tenant=>`<div class="trow property-contact-row"><span class="property-text"><b>${tenant.property}</b><small>${tenant.address||'Açık adres girilmedi'}</small></span><span class="property-meta">${tenant.owner||'Ev sahibi bilgisi girilmedi'}</span><span class="amount">${cash(tenant.rent)}</span><span class="tenant-contact"><b>${tenant.name}</b><small>${tenant.phone||'Telefon bilgisi girilmedi'}</small></span></div>`).join(''):'<p class="ticket-empty">Henüz gayrimenkul kaydı yok.</p>'}
