document.querySelectorAll('.payment-filter').forEach(button=>button.addEventListener('click',()=>{selectedPaymentFilter=button.dataset.paymentFilter;document.querySelectorAll('.payment-filter').forEach(item=>item.classList.toggle('active',item===button));applyPaymentFilter()}));
$('paymentSearch')?.addEventListener('input',applyPaymentFilter);$('paymentAddTenant')?.addEventListener('click',()=>$('modal').classList.add('open'));
const paymentDetailRender=render;render=function(){paymentDetailRender();let expected=tenants.filter(t=>!t.paymentDeleted&&!['Silindi','Feshedildi'].includes(t.payment)).reduce((total,t)=>total+Number(t.rent||0),0),paid=tenants.filter(t=>!t.paymentDeleted&&t.payment==='Ödendi').reduce((total,t)=>total+Number(t.rent||0),0),pending=Math.max(0,expected-paid),pendingCount=tenants.filter(t=>!t.paymentDeleted&&!['Ödendi','Silindi','Feshedildi'].includes(t.payment)).length,rate=expected?Math.round(paid/expected*100):0;if($('expectedPaymentDetail'))$('expectedPaymentDetail').textContent=`${tenants.length} kiracı · ${tenants.length} ödeme`;if($('collectedPaymentDetail'))$('collectedPaymentDetail').textContent=`%${rate} tahsilat oranı`;if($('remainingPaymentDetail'))$('remainingPaymentDetail').textContent=pendingCount?`${pendingCount} ödeme bekleniyor`:'Bekleyen ödeme yok';let summary=[...document.querySelectorAll('.payment-summary b')];if(summary.length>=3){summary[0].textContent=cash(expected);summary[1].textContent=cash(paid);summary[2].textContent=cash(pending)}};
function refreshPaymentOverview(){let live=tenants.filter(t=>!t.paymentDeleted&&!['Silindi','Feshedildi'].includes(t.payment)),expected=live.reduce((total,t)=>total+Number(t.rent||0),0),paid=live.filter(t=>t.payment==='Ödendi').reduce((total,t)=>total+Number(t.rent||0),0),pending=Math.max(0,expected-paid),pendingCount=live.filter(t=>t.payment!=='Ödendi').length,rate=expected?Math.round(paid/expected*100):0,summary=[...document.querySelectorAll('.payment-summary b')];if(summary.length>=3){summary[0].textContent=cash(expected);summary[1].textContent=cash(paid);summary[2].textContent=cash(pending)}if($('expectedPaymentDetail'))$('expectedPaymentDetail').textContent=`${live.length} kiracı · ${live.length} ödeme`;if($('collectedPaymentDetail'))$('collectedPaymentDetail').textContent=`%${rate} tahsilat oranı`;if($('remainingPaymentDetail'))$('remainingPaymentDetail').textContent=pendingCount?`${pendingCount} ödeme bekliyor`:'Bekleyen ödeme yok'}
