// Reference-aligned payments view: compact icon actions, stable right column and contextual delete menu.
const inlineIcon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.plus}</svg>`;
const polishedPaymentStatus=value=>`<span class="status ${value==='Ödendi'?'paid':value==='Gecikmiş'?'overdue':'pending'}">${inlineIcon(value==='Ödendi'?'check':'clock')}${value==='Ödendi'?'Ödendi':value==='Gecikmiş'?'Gecikmiş':'Bekliyor'}</span>`;
const polishedPaymentRender=render;
render=function(){
  polishedPaymentRender();
  const target=$('paymentTableRows');
  if(!target)return;
  document.querySelectorAll('#paymentFilterEmpty').forEach(item=>item.remove());
  const visiblePayments=tenants.map((tenant,index)=>({tenant,index})).filter(({tenant})=>!tenant.paymentDeleted);
  target.innerHTML=visiblePayments.length?visiblePayments.map(({tenant,index})=>{
    const receiptButton=tenant.receiptName
      ?`<button class="row-action view-receipt" data-receipt="${tenant.receiptName}">${inlineIcon('file')}Dekontu gör</button>`
      :`<button class="receipt-request-btn" data-index="${index}">${inlineIcon('file')}${tenant.receiptRequested?'Talep açık':'Dekont iste'}</button>`;
    return `<div class="trow payment-row" data-index="${index}">${person(tenant)}<span class="payment-period">${inlineIcon('calendar')}${tenant.periodLabel||'Bu ay'}</span><span class="amount">${cash(tenant.rent)}</span><span class="payment-due">${inlineIcon('calendar')}${tenant.dueLabel||`${tenant.day}. gün`}</span>${polishedPaymentStatus(displayPaymentStatus(tenant))}<span class="payment-actions"><button class="row-action paid" data-index="${index}">${inlineIcon('check')}Ödendi</button><button class="row-action remind-one" data-index="${index}">${inlineIcon('send')}Hatırlat</button>${receiptButton}<span class="payment-row-menu"><button class="row-action payment-more" type="button" data-index="${index}" aria-label="Diğer işlemler">${inlineIcon('more')}</button><button class="row-action delete-payment" data-index="${index}">Ödemeyi sil</button></span></span></div>`;
  }).join(''):'<p class="ticket-empty payment-empty">Henüz ödeme kaydı yok. Yeni kiracı eklediğinizde ödeme planı burada oluşur.</p>';
  target.insertAdjacentHTML('afterend','<p id="paymentFilterEmpty" class="ticket-empty" hidden>Bu filtreye uygun ödeme kaydı yok.</p>');
  applyPaymentFilter();
  refreshPaymentOverview();
};

$('paymentTableRows')?.addEventListener('click',event=>{
  const remind=event.target.closest('.remind-one'),more=event.target.closest('.payment-more');
  if(remind){const tenant=tenants[Number(remind.dataset.index)];if(tenant){localStorage.setItem('kiraPanelLatestNotice',`${tenant.name}: kira ödeme hatırlatması gönderildi.`);toast(`${tenant.name} için ödeme hatırlatması hazırlandı.`)}}
  if(more){event.stopPropagation();const menu=more.closest('.payment-row-menu');document.querySelectorAll('.payment-row-menu.open').forEach(item=>{if(item!==menu)item.classList.remove('open')});menu?.classList.toggle('open')}
});
document.addEventListener('click',event=>{if(!event.target.closest('.payment-row-menu'))document.querySelectorAll('.payment-row-menu.open').forEach(item=>item.classList.remove('open'))});
$('paymentFilterSettings')?.addEventListener('click',event=>{event.currentTarget.classList.toggle('active');$('paymentSearch')?.focus();toast('Durum filtreleri ve arama kullanıma hazır.')});
