// Locale-safe status codes and late-rendered tenant content. User supplied
// names, addresses and property titles deliberately remain untouched.
function paymentStatusCode(tenant){if(tenant?.paymentCode)return tenant.paymentCode;const value=displayPaymentStatus(tenant);return value==='Ödendi'?'PAID':value==='Gecikmiş'?'OVERDUE':value==='Feshedildi'?'TERMINATED':value==='Silindi'?'DELETED':'PENDING'}
function localeDate(value){if(!value)return '';return new Intl.DateTimeFormat(localeTag(),{day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(`${value}T12:00:00`))}
function translateTenantDetails(){
  const portal=$('tenantPortal');if(!portal)return;
  const profile=window.__pkTenantProfile||{};
  const name=profile.name||$('tenantLogout')?.querySelector('b')?.textContent?.trim()||'';
  const firstName=name.split(/\s+/).filter(Boolean)[0]||name;
  const heading=portal.querySelector('.tenant-welcome h1');if(heading)heading.textContent=`${tr('tenant.hello',{name:firstName})} 👋`;
  const art=portal.querySelector('.tenant-sidebar-art p');if(art)art.innerHTML=tr('tenantUi.sidebarSlogan').replace(' / ','<br>');
  const cards=portal.querySelectorAll('.tenant-card'),statusCode=paymentStatusCode(profile);
  if(cards[0]){const due=cards[0].querySelector('p');if(due)due.innerHTML=`${tr('tenant.due')} <b>${localeDate(profile.due_date)}</b>`;const badge=cards[0].querySelector('.status');if(badge)badge.textContent=tr(`common.${statusCode.toLowerCase()}`)}
  if(cards[1]){const end=profile.contract_end?new Date(`${profile.contract_end}T12:00:00`):null,days=end?Math.max(0,Math.ceil((end-Date.now())/86400000)):0,badge=portal.querySelector('.contract-badge');if(badge){if(badge.parentElement!==cards[1])cards[1].append(badge);badge.classList.add('contract-card-renewal');badge.innerHTML=`<i data-icon="calendar"></i><span>${tr('tenantUi.renewalIn')}</span><b>${tr('tenantUi.daysRemaining',{count:days})}</b>`}const detail=cards[1].querySelector('p');if(detail&&profile.contract_start)detail.textContent=`${localeDate(profile.contract_start)} — ${localeDate(profile.contract_end)}`}
  if(cards[2]){const detail=cards[2].querySelector('p');if(detail)detail.textContent=tr('tenantUi.ownerInfo')}
  const guide=$('paymentGuide');if(guide){const labels=guide.querySelectorAll('.iban-box small');if(labels[0])labels[0].textContent=tr('tenantUi.recipient');if(labels[1])labels[1].textContent='IBAN';const description=guide.querySelector('.payment-description small');if(description)description.textContent=tr('tenantUi.paymentDescription');const request=guide.querySelector('.receipt-request');if(request){const title=request.querySelector('b'),info=request.querySelector('span');if(title)title.textContent=tr('tenant.receiptOptional');if(info)info.textContent=tr('tenant.receiptOptionalInfo')}const fileInfo=guide.querySelector('.receipt-area>span');if(fileInfo&&!guide.querySelector('.receipt-area.has-file'))fileInfo.textContent=tr('tenantUi.fileInfo')}
  const notices=$('tenantNotifications')?.querySelectorAll('.tenant-notice')||[];
  const noticeContent=[['tenantUi.rentNotice','tenantUi.rentNoticeInfo'],['tenantUi.contractActive','tenantUi.contractActiveInfo'],['tenantUi.receiptNotice','tenantUi.receiptNoticeInfo']];
  notices.forEach((notice,index)=>{const pair=noticeContent[index];if(!pair)return;const title=notice.querySelector('b'),info=notice.querySelector('small');if(title)title.textContent=tr(pair[0]);if(info)info.textContent=tr(pair[1],{date:localeDate(index?profile.contract_end:profile.due_date)})});
  const history=portal.querySelector('.history-panel:not(#tenantAnnouncements)');if(history){const title=history.querySelector('.panel-header h3'),info=history.querySelector('.panel-header p'),empty=history.querySelector('.empty-approval');if(title)title.textContent=tr('tenant.history');if(info)info.textContent=tr('tenantUi.historyInfo');if(empty)empty.textContent=tr('tenantUi.historyEmpty');replaceOwnText(history.querySelector('.tenant-section-link'),tr('tenantUi.viewHistory'))}
  const help=$('tenantHelpCard');if(help){const info=help.querySelector('p');if(info)info.textContent=tr('tenantUi.helpInfo')}
  const profileNote=$('tenantLogout')?.querySelector('small');if(profileNote)profileNote.textContent=`${tr('tenantUi.role')} · ${tr('sidebar.logout')}`;
  paintIcons(portal);
}
const completeTenantTranslation=translateTenantInterface;translateTenantInterface=function(){completeTenantTranslation();translateTenantDetails()};
const profileAwareTenantLoader=loadTenantProfile;loadTenantProfile=async function(){await profileAwareTenantLoader();const token=localStorage.getItem('kiraPanelApiToken');if(token){try{const response=await fetch('/api/portal',{headers:{Authorization:`Bearer ${token}`}});if(response.ok)window.__pkTenantProfile=(await response.json()).profile||{}}catch(error){console.warn('Tenant locale profile unavailable',error)}}if(localeMessages[activeLanguage])translateTenantInterface()};

// Paid rows already communicate their state in the status column; removing the
// duplicate action prevents long RU/EN labels from colliding with neighbouring cells.
const collisionSafePaymentRender=render;render=function(){collisionSafePaymentRender();document.querySelectorAll('#paymentTableRows .payment-row').forEach(row=>{const tenant=tenants[Number(row.dataset.index)];if(paymentStatusCode(tenant)==='PAID')row.querySelector('.payment-actions .paid')?.remove()});if(localeMessages[activeLanguage])translateDynamicInterface()};
